// Generated by Cypress Author on 2026-10-19 (REL 01, 02) e 2026-10-22 (REL 03, 08)
//
// REL 01 · REL 02 (P0) · REL 03 · REL 08 (P1) — Plano_de_Testes_QA_MatchWallet.md §8.
// A geração do PDF e a regra "só com versão publicada" são do backend; a UI deve enviar o
// contrato certo e nunca mostrar sucesso quando a API recusa.

const CARTEIRA_ID = 'cart-1'

const DETALHE = {
  id: CARTEIRA_ID,
  nome: 'Carteira Moderada',
  perfilAlvo: 'MODERADO',
  descricao: null,
  ativa: true,
  criadoEm: '2026-01-01T00:00:00.000Z',
  versaoAtual: null,
}

describe('Plano QA · Relatórios (admin)', () => {
  beforeEach(() => {
    cy.bloquearApi()
    cy.stubSessao('admin')
    cy.stubApi('GET', `/carteiras/${CARTEIRA_ID}`, DETALHE, 'detalhe')
    cy.stubApi(
      'GET',
      `/carteiras/${CARTEIRA_ID}/versoes*`,
      { items: [], total: 0, page: 1, pageSize: 100 },
      'versoes',
    )

    cy.visit(`/admin/carteiras/${CARTEIRA_ID}`)
    cy.wait(['@detalhe', '@versoes'])
    cy.contains('[role="tab"]', 'Relatórios').click()
  })

  it('REL 01 · gera o relatório com competência e comentário → envia o contrato certo e confirma o arquivo', () => {
    cy.stubApi(
      'POST',
      '/relatorios/gerar',
      {
        statusCode: 201,
        body: {
          id: 'rel-1',
          carteiraId: CARTEIRA_ID,
          mesReferencia: '2026-10',
          nomeArquivo: 'carteira-moderada-2026-10.pdf',
          tamanhoBytes: 1024,
          geradoEm: '2026-10-19T12:00:00.000Z',
          downloadUrl: '/relatorios/rel-1/download',
        },
      },
      'gerar',
    )

    cy.get('[data-cy="relatorio-competencia"]').clear().type('2026-10')
    cy.get('[data-cy="relatorio-comentario"]').type('Mercado em alta, ação & "aspas".')
    cy.get('[data-cy="relatorio-gerar"]').click()

    cy.wait('@gerar').its('request.body').should('deep.equal', {
      carteiraId: CARTEIRA_ID,
      mesReferencia: '2026-10',
      comentarioMercado: 'Mercado em alta, ação & "aspas".',
    })
    cy.contains('Relatório de 2026-10 gerado (carteira-moderada-2026-10.pdf)').should('be.visible')
  })

  it('REL 02 · competência sem versão publicada → API recusa e a tela mostra o motivo, sem falso sucesso', () => {
    const mensagem = 'Não há versão publicada para a competência informada.'
    cy.stubErroApi(
      'POST',
      '/relatorios/gerar',
      { status: 422, code: 'VERSAO_NAO_PUBLICADA', message: mensagem },
      'gerar',
    )

    cy.get('[data-cy="relatorio-competencia"]').clear().type('2026-10')
    cy.get('[data-cy="relatorio-gerar"]').click()

    // Comentário em branco não é enviado (opcional).
    cy.wait('@gerar').its('request.body').should('not.have.property', 'comentarioMercado')
    cy.contains(mensagem).should('be.visible')
    cy.contains('gerado (').should('not.exist')
    cy.get('[data-cy="relatorio-gerar"]').should('be.enabled')
  })

  it('REL 03 · comentário opcional e texto com acentos, quebras de linha e HTML → enviado intacto, sem executar marcação, e o campo limpa após o sucesso', () => {
    cy.stubApi(
      'POST',
      '/relatorios/gerar',
      {
        statusCode: 201,
        body: {
          id: 'rel-3',
          carteiraId: CARTEIRA_ID,
          mesReferencia: '2026-10',
          nomeArquivo: 'carteira-moderada-2026-10.pdf',
          tamanhoBytes: 2048,
        },
      },
      'gerar',
    )
    const html = '<img src=x onerror="window.__xss=1"> <b>ação</b>'

    // Sem comentário: o campo some do contrato.
    cy.get('[data-cy="relatorio-competencia"]').clear().type('2026-10')
    cy.get('[data-cy="relatorio-gerar"]').click()
    cy.wait('@gerar').its('request.body').should('not.have.property', 'comentarioMercado')
    cy.contains('Relatório de 2026-10 gerado').should('be.visible')

    // Com acentos, quebra de linha e HTML.
    cy.get('[data-cy="relatorio-comentario"]').type('Câmbio e previdência: ação ç ã.{enter}')
    cy.get('[data-cy="relatorio-comentario"]').type(html)
    cy.get('[data-cy="relatorio-gerar"]').should('be.enabled').click()
    cy.wait('@gerar')
      .its('request.body.comentarioMercado')
      .should('eq', `Câmbio e previdência: ação ç ã.\n${html}`)
    cy.get('img[src="x"]').should('not.exist')
    cy.window().its('__xss').should('not.exist')
    cy.get('[data-cy="relatorio-comentario"]').should('have.value', '')
  })

  it('REL 03 · competência vazia ou malformada recusada pelo servidor → motivo exibido, sem falso sucesso e botão liberado', () => {
    cy.intercept('POST', '**/api/v1/relatorios/gerar', {
      statusCode: 400,
      body: {
        error: { code: 'VALIDATION_ERROR', message: 'Informe a competência no formato AAAA-MM.' },
      },
    }).as('gerar')

    for (const competencia of ['', '2026-13', '2026-00', '26-10']) {
      cy.get('[data-cy="relatorio-competencia"]').clear()
      if (competencia) cy.get('[data-cy="relatorio-competencia"]').type(competencia)
      cy.get('[data-cy="relatorio-gerar"]').click()
      cy.wait('@gerar').its('request.body.mesReferencia').should('eq', competencia)
      cy.contains('Informe a competência no formato AAAA-MM.').should('be.visible')
      cy.contains('gerado (').should('not.exist')
      cy.get('[data-cy="relatorio-gerar"]').should('be.enabled')
    }
  })

  it('REL 08 · resposta perdida e nova tentativa → erro sem falso sucesso; o 409 do servidor aparece como recusa, sem duplicar', () => {
    // A UI nunca envia `forcar`: depois do 409 não há caminho de reemissão pela tela. Isso é
    // lacuna de produto a registrar; a substituição (`forcar: true`) só é testada na API real.
    let chamadas = 0
    cy.intercept('POST', '**/api/v1/relatorios/gerar', (req) => {
      chamadas += 1
      if (chamadas === 1) {
        // O servidor pode ter gerado, mas o navegador não recebeu a resposta.
        req.destroy()
        return
      }
      req.reply({
        statusCode: 409,
        body: {
          error: {
            code: 'CONFLICT',
            message: 'Já existe um relatório gerado para esta carteira nesta competência.',
          },
        },
      })
    }).as('gerar')

    cy.get('[data-cy="relatorio-competencia"]').clear().type('2026-10')
    cy.get('[data-cy="relatorio-gerar"]').click()
    cy.contains('Não foi possível gerar o relatório.').should('be.visible')
    cy.contains('gerado (').should('not.exist')

    cy.get('[data-cy="relatorio-gerar"]').should('be.enabled').click()
    cy.contains('Já existe um relatório gerado para esta carteira nesta competência.').should(
      'be.visible',
    )
    cy.contains('gerado (').should('not.exist')
    cy.get('@gerar.all').should('have.length', 2)
    cy.get('@gerar.all').each((chamada) => {
      expect(
        (chamada as unknown as { request: { body: object } }).request.body,
      ).not.to.have.property('forcar')
    })
  })
})

export {}
